package com.ronpark.interview;

import android.app.Activity;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;

/** Native layout shared by the synchronized Debug screens only. */
abstract class InterviewTestScreen extends Activity {
    final int ink=0xff152c43,teal=0xff087d72,sub=0xff65778a,paper=0xfff6f8fa;
    LinearLayout content;
    ScrollView scroll;
    private PopupWindow choices;
    @Override public void onCreate(android.os.Bundle state){super.onCreate(state);if(android.os.Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::onBackPressed);}
    int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(7),0,dp(7));return t;}
    TextView add(String value,int size,int color){TextView t=text(value,size,color);content.addView(t);return t;}
    void title(String value){TextView t=add(value,26,ink);t.setTypeface(null,Typeface.BOLD);}
    Button button(String title,boolean primary,Runnable action){Button b=new Button(this){@Override public void setEnabled(boolean enabled){super.setEnabled(enabled);setAlpha(enabled?1f:.45f);}};b.setText(title);b.setAllCaps(false);b.setTextSize(17);b.setTypeface(android.os.Build.VERSION.SDK_INT>=28?Typeface.create(Typeface.DEFAULT,600,false):Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setTextColor(primary?Color.WHITE:teal);b.setBackground(bg(primary?teal:Color.WHITE,16));b.setMinHeight(dp(50));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(18);content.addView(b,lp);b.setOnClickListener(v->action.run());b.setOnTouchListener((v,event)->{if(android.os.Build.VERSION.SDK_INT<26||android.animation.ValueAnimator.areAnimatorsEnabled()){if(event.getActionMasked()==android.view.MotionEvent.ACTION_DOWN)v.animate().scaleX(.98f).scaleY(.98f).setDuration(90).start();if(event.getActionMasked()==android.view.MotionEvent.ACTION_UP||event.getActionMasked()==android.view.MotionEvent.ACTION_CANCEL)v.animate().scaleX(1).scaleY(1).setDuration(150).start();}return false;});return b;}
    LinearLayout card(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(12),dp(16),dp(16));box.setBackground(bg(Color.WHITE,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(18);content.addView(box,lp);return box;}
    void disclosure(String title,String body){LinearLayout group=new LinearLayout(this);group.setOrientation(LinearLayout.VERTICAL);TextView heading=text(title+"  ›",15,teal),details=text(body,14,ink);details.setVisibility(View.GONE);heading.setOnClickListener(v->{boolean expanded=details.getVisibility()==View.VISIBLE;details.setVisibility(expanded?View.GONE:View.VISIBLE);heading.setText(title+(expanded?"  ›":"  ▾"));});group.addView(heading);group.addView(details);content.addView(group);}
    LinearLayout dropdown(String title,String value,java.util.function.Consumer<View> action,boolean enabled){LinearLayout group=new LinearLayout(this);group.setOrientation(LinearLayout.VERTICAL);TextView caption=text(title,12,sub);caption.setPadding(0,0,0,dp(7));group.addView(caption);TextView option=text(value+"  ▾",14,ink);option.setPadding(dp(12),dp(10),dp(12),dp(10));option.setMinHeight(dp(48));GradientDrawable background=bg(Color.WHITE,10);background.setStroke(dp(1),0x47777777);option.setBackground(background);option.setGravity(Gravity.CENTER_VERTICAL);option.setOnClickListener(action::accept);option.setEnabled(enabled);option.setAlpha(enabled?1f:.45f);option.setContentDescription(title+", "+value);group.addView(option,new LinearLayout.LayoutParams(-1,-2));return group;}
    void choose(View anchor,String[] labels,int selected,java.util.function.IntConsumer changed){
        if(choices!=null)choices.dismiss();LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);rows.setPadding(0,dp(4),0,dp(4));
        for(int i=0;i<labels.length;i++){final int index=i;TextView row=text((i==selected?"✓   ":"     ")+labels[i],16,ink);row.setPadding(dp(16),dp(10),dp(16),dp(10));row.setGravity(Gravity.CENTER_VERTICAL);row.setMinHeight(dp(44));row.setContentDescription(labels[i]+(i==selected?", 선택됨":""));rows.addView(row,new LinearLayout.LayoutParams(-1,-2));row.setOnClickListener(v->{choices.dismiss();changed.accept(index);});if(i<labels.length-1){View line=new View(this);line.setBackgroundColor(0x14777777);rows.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}}
        ScrollView menu=new ScrollView(this);menu.addView(rows);android.graphics.Paint measure=new android.graphics.Paint();measure.setTextSize(16*getResources().getDisplayMetrics().scaledDensity);int natural=dp(230);for(String label:labels)natural=Math.max(natural,(int)measure.measureText(label)+dp(56));int width=Math.min(Math.min(natural,dp(300)),getResources().getDisplayMetrics().widthPixels-dp(24)),height=Math.min(dp(8+labels.length*45),getResources().getDisplayMetrics().heightPixels/2);
        choices=new PopupWindow(menu,width,height,true);choices.setBackgroundDrawable(bg(Color.WHITE,14));choices.setElevation(dp(12));choices.setOutsideTouchable(true);int[] location=new int[2];anchor.getLocationOnScreen(location);int x=Math.max(dp(12),Math.min(location[0],getResources().getDisplayMetrics().widthPixels-width-dp(12))),y=location[1]+anchor.getHeight();if(y+height>getResources().getDisplayMetrics().heightPixels-dp(24))y=Math.max(dp(24),location[1]-height);choices.showAtLocation(anchor,Gravity.TOP|Gravity.LEFT,x,y);
    }
    void confirm(String title,String message,String negative,String positive,Runnable accepted){
        android.app.Dialog dialog=new android.app.Dialog(this);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(14),dp(16),0);box.setBackground(bg(Color.WHITE,14));TextView heading=text(title,17,ink);heading.setTypeface(null,Typeface.BOLD);heading.setGravity(Gravity.CENTER);box.addView(heading);TextView body=text(message,13,ink);body.setGravity(Gravity.CENTER);box.addView(body);String[] labels={positive,negative};for(int i=0;i<2;i++){final boolean yes=i==0;View divider=new View(this);divider.setBackgroundColor(0x24777777);box.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));TextView action=text(labels[i],16,yes?0xffd93636:teal);action.setGravity(Gravity.CENTER);action.setMinHeight(dp(44));box.addView(action);action.setOnClickListener(v->{dialog.dismiss();if(yes)accepted.run();});}dialog.setContentView(box);dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.show();dialog.getWindow().setLayout(dp(280),-2);
    }
    @Override public void onConfigurationChanged(android.content.res.Configuration configuration){super.onConfigurationChanged(configuration);if(choices!=null)choices.dismiss();}
    @Override protected void onDestroy(){if(choices!=null)choices.dismiss();super.onDestroy();}
    void beginLayout(String name){
        getWindow().setStatusBarColor(paper);getWindow().setNavigationBarColor(paper);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(paper);FrameLayout header=new FrameLayout(this);root.addView(header,new LinearLayout.LayoutParams(-1,dp(48)));TextView label=text(name,17,ink);label.setGravity(Gravity.CENTER);label.setTypeface(null,Typeface.BOLD);header.addView(label,new FrameLayout.LayoutParams(-1,-1));TextView back=text("돌아가기",15,teal);back.setGravity(Gravity.CENTER_VERTICAL);back.setPadding(dp(16),0,dp(16),0);back.setOnClickListener(v->onBackPressed());header.addView(back,new FrameLayout.LayoutParams(-2,-1,Gravity.LEFT));
        scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(paper);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(24),dp(24),dp(24),dp(24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
        root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
    }
}
